try{ if(typeof ART_IMG!=='undefined'){ /* merged into ART_IMG */ void 0; } }catch(e){}
window.FAC_IMG = {"annex": "data:image/webp;base64,", "campus": "data:image/webp;base64,", "tower": "data:image/webp;base64,", "global": "data:image/webp;base64,"};
window.HQ_IMG = {};

try{
  if(typeof facilitiesSection==='function'){
    var _origFac = facilitiesSection;
    facilitiesSection = function(){
      var box = _origFac.apply(this, arguments);
      try{
        box.querySelectorAll('[data-v17fac]').forEach(function(b){
          var k = b.getAttribute('data-v17fac');
          var src = window.FAC_IMG[k];
          if(!src || b.querySelector('img')) return;
          var span = document.createElement('span');
          span.className = 'fac-txt';
          while(b.firstChild){ span.appendChild(b.firstChild); }
          var img = document.createElement('img');
          img.src = src; img.alt = '';
          b.appendChild(span);
          b.insertBefore(img, b.firstChild);
          b.classList.add('fac-card');
        });
      }catch(e){}
      return box;
    };
  }
}catch(e){}
